-- =============================================================================
-- 527 — LE CAHIER D'EXERCICES DE 1RE (partie 15)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 527 --niveau 1re --fichiers francais.n19a,francais.n19b,francais.n1a,francais.n1b,francais.n20a --suffixe 15 > supabase/contenu/527_exercices_1re_15.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n19a           18 exercices · 6 chapitres
--   francais.n19b           18 exercices · 6 chapitres
--   francais.n1a            18 exercices · 6 chapitres
--   francais.n1b            18 exercices · 6 chapitres
--   francais.n20a           18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('6ba23211-f8fd-5192-929f-d946239dd569'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ulysse, dix ans après Troie","competence":"analyser-document","situation":"Tu prépares une fiche de lecture sur l’*Odyssée*. Commence par la carte d’identité du poème, puis regarde qui attend Ulysse à Ithaque.","documents":[{"id":"carte","type":"fiche","modele":"affiche","entete":"L’Odyssée","sousTitre":"Récit du retour d’Ulysse","emoji":"⛵","lignes":[{"texte":"Auteur","valeur":"Homère (attribué)","id":"z1"},{"texte":"Époque","valeur":"VIIIe siècle av. J.-C.","id":"z2"},{"texte":"Forme","valeur":"Vingt-quatre chants","id":"z3"},{"texte":"Héros","valeur":"Ulysse, roi d’Ithaque","id":"z4"}],"pied":"Suite de l’*Iliade*","teinte":"violet"},{"id":"ithaque","type":"tableau","titre":"À Ithaque, pendant l’absence d’Ulysse","colonnes":["Personnage","Situation"],"lignes":[["Télémaque","Il grandit sans son père"],["Pénélope","?"],["Athéna","Elle obtient des dieux le retour d’Ulysse"]],"enteteLignes":true}],"questions":[{"enonce":"Sur la carte d’identité, touche la ligne qui dit à quelle époque le poème a été composé.","aide":"Cherche une indication de siècle.","type":"zone","document":"carte","multiple":false},{"enonce":"Complète la phrase avec la carte d’identité du poème.","aide":"Tout est sur la carte ; le dernier mot est le thème du poème.","type":"trous","segments":["Le poème, attribué à ",0,", est composé de ",1," chants et raconte le ",2," d’Ulysse chez lui."],"banque":["vingt-quatre","départ","Homère","douze","retour","Virgile"]},{"enonce":"Que faut-il écrire dans la case « ? » du tableau, pour Pénélope ?","aide":"Pénélope est restée au palais : qui s’y est installé ?","type":"choix","options":[{"id":"a","texte":"Elle est assiégée par des prétendants qui pillent le palais"},{"id":"b","texte":"Elle part chercher des nouvelles de son mari au loin"},{"id":"c","texte":"Elle accompagne Ulysse dans tous ses voyages en mer"},{"id":"d","texte":"Elle règne seule, honorée de tous les Grecs d’Ithaque"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le poème est composé au **VIIIe siècle av. J.-C.**, à partir d’une tradition orale."},{"cle":{"type":"trous","trous":[["homere"],["vingt quatre","24"],["retour"]]},"affichage":"Homère · vingt-quatre · retour","explication":"Le poème d’**Homère** compte **vingt-quatre** chants : c’est le récit du **retour** (*nostos*) d’Ulysse."},{"cle":{"type":"choix","ids":["a"]},"explication":"Pénélope est **assiégée par des prétendants** qui pillent le palais : elle résiste en attendant Ulysse."}]$ex$::jsonb),
  ('6ba23211-f8fd-5192-929f-d946239dd569'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le long chemin du retour","competence":"analyser-texte","situation":"Un camarade t’a écrit un résumé de l’*Odyssée* pour t’aider. Lis-le, puis suis le dernier fil du poème : le retour au palais.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"Le résumé de ton camarade","blocs":["Dix ans après la chute de Troie, Ulysse n’est toujours pas rentré. À Ithaque, son fils Télémaque part chercher des nouvelles : c’est la Télémachie.","Chez les Phéaciens, le héros raconte lui-même ses aventures : le Cyclope, Circé, les Sirènes. Puis il rentre, déguisé en mendiant."],"source":"Résumé écrit pour l’exercice"},{"id":"retour","type":"chaine","titre":"Le retour au palais","disposition":"colonne","noeuds":[{"id":"z1","texte":"Ulysse arrive déguisé en mendiant"},{"id":"z2","texte":"Son chien Argos et sa nourrice le reconnaissent"},{"id":"z3","texte":"Il est le seul à pouvoir bander l’arc"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Pénélope l’éprouve par le secret du lit"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche le personnage qui part chercher des nouvelles de son père.","aide":"C’est le fils d’Ulysse.","type":"zone","document":"resume","multiple":false},{"enonce":"Touche le mot qui désigne le déguisement d’Ulysse à son retour.","aide":"Un homme qui demande l’aumône.","type":"zone","document":"resume","multiple":false},{"enonce":"Quelle étape manque dans la chaîne du retour (la case « ? ») ?","aide":"Entre l’épreuve de l’arc et l’ultime épreuve, Ulysse doit se débarrasser de ceux qui pillent le palais.","type":"choix","options":[{"id":"a","texte":"Le massacre des prétendants et la reprise du palais"},{"id":"b","texte":"Les dieux détruisent le palais d’Ithaque et ses murs"},{"id":"c","texte":"Ulysse repart aussitôt vers de nouvelles îles lointaines"},{"id":"d","texte":"Télémaque quitte Ithaque pour un nouveau voyage"}],"multiple":false},{"enonce":"Relie chaque fil du poème à ce qu’il raconte.","aide":"Relis le résumé et la chaîne : qui parle, et où ?","type":"association","gauche":[{"id":"g0","texte":"La Télémachie"},{"id":"g1","texte":"Les récits chez les Phéaciens"},{"id":"g2","texte":"Le retour"}],"droite":[{"id":"d0","texte":"Déguisé en mendiant, Ulysse reprend son palais"},{"id":"d1","texte":"Le fils part chercher des nouvelles de son père"},{"id":"d2","texte":"Ulysse raconte lui-même ses aventures"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"Le fils d’Ulysse, **Télémaque**, part à la recherche de son père : c’est le premier fil du poème."},{"cle":{"type":"zone","ids":["m45"]},"explication":"Ulysse rentre déguisé en **mendiant** : personne ne le reconnaît tout de suite."},{"cle":{"type":"choix","ids":["a"]},"explication":"Après l’arc vient le **massacre des prétendants** : Ulysse reprend son palais, puis Pénélope l’éprouve."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La **Télémachie** suit le fils ; les **récits** sont dits par Ulysse chez les Phéaciens ; le **retour** est celui du mendiant qui reprend son palais."}]$ex$::jsonb),
  ('6ba23211-f8fd-5192-929f-d946239dd569'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Personne contre le géant","competence":"argumenter","situation":"Deux élèves se disputent : Ulysse triomphe-t-il du Cyclope par la force ou par autre chose ? Lis une scène écrite pour l’exercice, à la manière d’Homère, et tranche.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Chez le Cyclope","blocs":["Le géant a déjà dévoré deux compagnons. L’homme aux mille tours lui tend alors une outre de vin pur.","« Quel est ton nom, étranger ? demande le monstre. Je veux te faire un présent. — Mon nom est Personne », répond le héros.","Quand le Cyclope ivre s’endort, les Grecs enfoncent un pieu rougi au feu dans son unique œil. Ses cris attirent les voisins, qui demandent qui lui fait du mal. Il hurle que nul ne l’attaque par la force, et les voisins s’éloignent."],"source":"Texte écrit pour l’exercice, à la manière d’Homère"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Sami","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Ulysse gagne parce qu’il est le plus fort des Grecs."},{"qui":"Sami","texte":"Non : un géant ne se bat pas à armes égales. Il lui faut un plan."},{"qui":"Lina","texte":"Quel plan, avec un simple nom ?"},{"qui":"Sami","texte":"Justement : il le trompe avec un faux nom et le rend ivre d’abord."}]}],"questions":[{"enonce":"Touche l’objet qu’Ulysse offre au géant pour l’endormir.","aide":"C’est un contenant en peau, rempli de vin.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche le faux nom sous lequel Ulysse se présente.","aide":"Un nom qui signifie l’absence de quelqu’un.","type":"zone","document":"scene","multiple":false},{"enonce":"Quelle lecture la scène prouve-t-elle ?","aide":"Relis ce qu’Ulysse offre, puis le nom qu’il donne : sont-ce des armes ?","type":"choix","options":[{"id":"a","texte":"Ulysse est secouru par les dieux, qui tuent le géant pour lui"},{"id":"b","texte":"Ulysse est un lâche qui abandonne ses compagnons dès le début"},{"id":"c","texte":"Ulysse est un héros brutal que seule sa force sauve du danger"},{"id":"d","texte":"Ulysse est un héros de l’intelligence : la ruse l’emporte sur la force"}],"multiple":false},{"enonce":"Relie chaque procédé du poème à son effet.","aide":"Pense à qui parle, à ce que veut le héros, et à ce que fait le mot « Personne ».","type":"association","gauche":[{"id":"g0","texte":"Le récit enchâssé"},{"id":"g1","texte":"Le nostos"},{"id":"g2","texte":"Le faux nom « Personne »"}],"droite":[{"id":"d0","texte":"Ulysse raconte lui-même ses aventures"},{"id":"d1","texte":"La ruse retourne les mots contre le géant"},{"id":"d2","texte":"Tout le poème tend vers le retour chez soi"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"Ulysse offre une **outre** de vin pur : l’ivresse du géant prépare sa défaite."},{"cle":{"type":"zone","ids":["m37"]},"explication":"Ulysse se fait appeler « **Personne** » : quand le géant crie, ses voisins croient que nul ne lui fait de mal."},{"cle":{"type":"choix","ids":["d"]},"explication":"La scène repose sur une **ruse** (le vin, le faux nom) : Ulysse est « aux mille tours », un héros de l’**intelligence**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Le **récit enchâssé** donne la parole à Ulysse ; le **nostos** est le retour ; le nom « **Personne** » est une arme de ruse."}]$ex$::jsonb),
  ('cd89d041-1e35-5f9b-9e85-11cf60e662ba'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un roi de Thèbes sur la scène d’Athènes","competence":"se-reperer-temps","situation":"Pour ton oral, tu situes *Œdipe roi* dans la vie de Sophocle, puis tu rappelles qui est qui dans la pièce.","documents":[{"id":"frise","type":"frise","titre":"Sophocle et sa pièce","debut":-500,"fin":-400,"pas":20,"evenements":[{"id":"z1","date":-496,"nom":"Naissance"},{"id":"z2","date":-425,"nom":"Œdipe roi (vers)"},{"id":"z3","date":-406,"nom":"Mort"}]},{"id":"persos","type":"tableau","titre":"Les personnages","colonnes":["Personnage","Rôle"],"lignes":[["Œdipe","Roi de Thèbes, qui mène l’enquête"],["Jocaste","Veuve de Laïos, devenue l’épouse d’Œdipe"],["Tirésias","?"],["Créon","Beau-frère d’Œdipe, accusé de complot"]],"enteteLignes":true}],"questions":[{"enonce":"Touche, sur la frise, le repère qui correspond à la pièce.","aide":"Cherche le titre de l’œuvre.","type":"zone","document":"frise","multiple":false},{"enonce":"Complète avec ce que tu sais du cadre de la pièce.","aide":"Le roi est de Thèbes, mais la pièce est jouée dans une autre cité.","type":"trous","segments":["La pièce est jouée à ",0,", lors des concours du théâtre de ",1,"."],"banque":["Apollon","Thèbes","Athènes","Corinthe","Dionysos"]},{"enonce":"Quel rôle faut-il écrire dans la case « ? » du tableau, pour Tirésias ?","aide":"C’est lui qui accuse Œdipe le premier.","type":"choix","options":[{"id":"a","texte":"Le devin qui, contraint de parler, accuse Œdipe"},{"id":"b","texte":"Le berger qui a recueilli l’enfant sur la montagne"},{"id":"c","texte":"Le messager venu de Corinthe annoncer une mort"},{"id":"d","texte":"Le chef du chœur des vieillards thébains"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La pièce est jouée **vers 430-420 av. J.-C.**, du vivant de Sophocle."},{"cle":{"type":"trous","trous":[["athenes"],["dionysos"]]},"affichage":"Athènes · Dionysos","explication":"La pièce est jouée à **Athènes**, lors des concours du théâtre de **Dionysos**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le devin **Tirésias**, contraint de parler, **accuse** Œdipe d’être le meurtrier de Laïos."}]$ex$::jsonb),
  ('cd89d041-1e35-5f9b-9e85-11cf60e662ba'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quand le juge devient le coupable","competence":"analyser-document","situation":"La pièce est une enquête menée par un roi. Suis les étapes de cette enquête, depuis la peste jusqu’à la vérité.","documents":[{"id":"enquete","type":"chaine","titre":"L’enquête d’Œdipe","disposition":"colonne","noeuds":[{"id":"z1","texte":"La peste frappe Thèbes"},{"id":"z2","texte":"L’oracle exige de chasser le meurtrier de Laïos"},{"id":"z3","texte":"Tirésias accuse Œdipe"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Un messager et un vieux berger parlent"},{"id":"z6","texte":"Œdipe découvre qu’il est le fils de Laïos"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"},{"de":"z5","a":"z6"}]}],"questions":[{"enonce":"Que répond Œdipe à Tirésias (la case « ? ») ?","aide":"Œdipe refuse de croire le devin et cherche un instigateur.","type":"choix","options":[{"id":"a","texte":"Il crie au complot de Créon"},{"id":"b","texte":"Il quitte Thèbes aussitôt après"},{"id":"c","texte":"Il remercie le devin de sa franchise"},{"id":"d","texte":"Il demande pardon à Jocaste"}],"multiple":false},{"enonce":"Touche l’étape où éclate la vérité sur sa naissance.","aide":"Après les témoignages, il comprend qui sont ses parents.","type":"zone","document":"enquete","multiple":false},{"enonce":"Remets dans l’ordre les événements de la fin de la pièce.","aide":"Jocaste agit la première ; Œdipe réagit à la vérité.","type":"ordre","items":[{"id":"a","texte":"Œdipe réclame l’exil"},{"id":"b","texte":"Jocaste se pend"},{"id":"c","texte":"Œdipe se crève les yeux"}]},{"enonce":"Relie chaque personnage à ce qui le définit.","aide":"Chaque personnage a un geste ou un rôle précis dans l’enquête.","type":"association","gauche":[{"id":"g0","texte":"Tirésias"},{"id":"g1","texte":"Créon"},{"id":"g2","texte":"Jocaste"},{"id":"g3","texte":"Le chœur"}],"droite":[{"id":"d0","texte":"Accusé à tort de complot"},{"id":"d1","texte":"Vieillards thébains qui commentent l’action"},{"id":"d2","texte":"Reine, elle se pend à la fin"},{"id":"d3","texte":"Aveugle, il voit la vérité"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"Œdipe **crie au complot de Créon** : il refuse l’accusation et la retourne contre son beau-frère."},{"cle":{"type":"zone","ids":["z6"]},"explication":"La révélation est l’étape où Œdipe découvre qu’il est le **fils** de Laïos et de Jocaste."},{"cle":{"type":"ordre","ids":["b","c","a"]},"explication":"D’abord **Jocaste se pend**, puis **Œdipe se crève les yeux** avec les agrafes de sa robe, et **réclame l’exil**."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"**Tirésias** voit la vérité malgré sa cécité ; **Créon** est accusé à tort ; **Jocaste** se pend ; le **chœur** commente."}]$ex$::jsonb),
  ('cd89d041-1e35-5f9b-9e85-11cf60e662ba'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le spectateur sait, le roi ignore","competence":"argumenter","situation":"Deux élèves se demandent si une pièce dont on connaît la fin peut encore tenir en haleine. Lis une scène écrite pour l’exercice, à la manière de Sophocle, puis tranche.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Un roi promet justice","blocs":[{"didascalie":"Une cité frappée par un fléau. Le spectateur connaît déjà la vérité sur le roi."},{"personnage":"Le roi","replique":"Je maudis le coupable : qu’il soit chassé de la ville, fût-il l’un des miens."},{"personnage":"Le chœur","replique":"Roi, nous t’écoutons avec crainte."}],"source":"Texte écrit pour l’exercice, à la manière de Sophocle"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"On connaît la fin : la pièce ne peut pas nous surprendre."},{"qui":"Malik","texte":"L’intérêt est ailleurs : on connaît le mythe, et on voit le roi courir à sa perte."}]}],"questions":[{"enonce":"Touche les deux verbes par lesquels le roi condamne le coupable.","aide":"Un verbe de malédiction, un verbe d’exil.","type":"zone","document":"scene","multiple":true},{"enonce":"Touche le mot qui explique pourquoi le spectateur n’est pas surpris.","aide":"Ce mot désigne une histoire que tout le monde connaît.","type":"zone","document":"deb","multiple":false},{"enonce":"Qu’appelle-t-on ironie tragique dans la pièce ?","aide":"Relis la didascalie : qui sait quoi ?","type":"choix","options":[{"id":"a","texte":"Le spectateur sait ce que le roi ignore"},{"id":"b","texte":"Un personnage comique vient détendre l’atmosphère de la pièce"},{"id":"c","texte":"Le roi plaisante sur son malheur et sur le sort de son peuple"},{"id":"d","texte":"Le chœur se moque du roi et de ses courtisans dans chaque scène"}],"multiple":false},{"enonce":"Range chacun selon qu’il voit la vérité ou qu’il en est aveugle.","aide":"Pense au paradoxe de la pièce : la vue et la vérité ne vont pas ensemble.","type":"categories","categories":[{"id":"c0","texte":"Voit la vérité"},{"id":"c1","texte":"Est aveugle à la vérité"}],"items":[{"id":"i0","texte":"Œdipe, qui a de bons yeux"},{"id":"i1","texte":"Tirésias, qui est aveugle"},{"id":"i2","texte":"Œdipe avant l’enquête"},{"id":"i3","texte":"Le spectateur, qui connaît le mythe"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m22"]},"explication":"Le roi **maudit** et veut **chasser** le coupable : sa menace se retournera contre lui, c’est l’**ironie tragique**."},{"cle":{"type":"zone","ids":["m18"]},"explication":"Les spectateurs connaissent le **mythe** : l’intérêt vient de la manière dont la vérité éclate."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il y a **ironie tragique** quand le **spectateur sait** et que le **héros ignore** : chaque menace se retourne contre lui."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**Tirésias** et le **spectateur** voient la vérité ; **Œdipe**, qui voit, est **aveugle**."}]$ex$::jsonb),
  ('2a782013-315c-5d55-b100-bef54de97ec8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une pièce faite pour la lecture","competence":"se-reperer-temps","situation":"Tu prépares ta fiche sur *On ne badine pas avec l’amour*. Note les dates clés, puis qui est qui dans la pièce.","documents":[{"id":"carte","type":"fiche","modele":"affiche","entete":"On ne badine pas avec l’amour","sousTitre":"Alfred de Musset","emoji":"🌹","lignes":[{"texte":"Genre","valeur":"Proverbe en trois actes","id":"z1"},{"texte":"Publication","valeur":"1834","id":"z2"},{"texte":"Créée sur scène","valeur":"1861","id":"z3"},{"texte":"Où ?","valeur":"Revue des Deux Mondes","id":"z4"}],"pied":"Musset est mort en 1857","teinte":"rose"},{"id":"persos","type":"tableau","titre":"Les personnages","colonnes":["Personnage","Ce qu’il incarne"],"lignes":[["Perdican","La jeunesse fière, l’amour de la vie"],["Camille","?"],["Rosette","L’innocence sacrifiée"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui dit quand la pièce a été jouée pour la première fois.","aide":"Elle n’est créée qu’après la mort de Musset.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien d’années séparent la publication de la création sur scène ?","aide":"Soustrais les deux années de la fiche.","type":"nombre","unite":"ans"},{"enonce":"Que faut-il écrire dans la case « ? » pour Camille ?","aide":"Les religieuses lui ont fait peur de l’infidélité des hommes.","type":"choix","options":[{"id":"a","texte":"La naïveté joyeuse d’une jeune paysanne"},{"id":"b","texte":"La sagesse d’un chœur de villageois"},{"id":"c","texte":"Le comique des fantoches de la maison"},{"id":"d","texte":"La méfiance, l’orgueil, la peur d’être trahie"}],"multiple":false}]}$ex$::jsonb,
