   $ex${"titre":"On aime malgré tout","competence":"argumenter","situation":"Deux élèves discutent de la célèbre tirade de Perdican : dit-elle qu’il faut fuir l’amour ? Lis la phrase de Musset et tranche.","documents":[{"id":"tirade","type":"texte","genre":"theatre","titre":"Perdican parle à Camille","blocs":[{"personnage":"Perdican","replique":"On est souvent trompé en amour, souvent blessé et souvent malheureux ; mais on aime."}],"source":"Alfred de Musset, *On ne badine pas avec l’amour* (1834), acte II"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Zoé","emoji":"👧","cote":"gauche"},{"nom":"Basile","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoé","texte":"Perdican énumère les malheurs de l’amour : il conseille de s’en détourner."},{"qui":"Basile","texte":"Il finit pourtant par une affirmation : l’amour vaut d’être vécu."}]}],"questions":[{"enonce":"Touche les trois mots par lesquels la phrase se retourne en affirmation.","aide":"Après le point-virgule, la phrase change de direction.","type":"zone","document":"tirade","multiple":true},{"enonce":"À laquelle des deux élèves la phrase donne-t-elle raison ?","aide":"Regarde comment la phrase se termine.","type":"choix","options":[{"id":"a","texte":"Aux deux : Perdican se contredit sans même s’en rendre compte"},{"id":"b","texte":"À Basile : malgré les blessures, l’amour vaut d’être vécu"},{"id":"c","texte":"À aucune : la phrase ne parle pas de l’amour du tout"},{"id":"d","texte":"À Zoé : il faut renoncer à l’amour pour ne plus souffrir"}],"multiple":false},{"enonce":"Range chaque élément de la pièce selon le registre dominant.","aide":"Les fantoches font rire, la tirade fait chanter l’amour, la fin fait pleurer.","type":"categories","categories":[{"id":"c0","texte":"Comique"},{"id":"c1","texte":"Lyrique"},{"id":"c2","texte":"Tragique"}],"items":[{"id":"i0","texte":"Les fantoches de la maison du baron"},{"id":"i1","texte":"Maître Blazius, maître Bridaine et dame Pluc