  ('af6e9125-0bfc-5b69-be53-f185ad755def'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Faire vrai, ce n’est pas tout dire","competence":"argumenter","situation":"Dans la préface de *Pierre et Jean*, Maupassant s’explique sur le réalisme. Deux élèves en tirent deux lectures : à toi de trancher.","documents":[{"id":"preface","type":"texte","genre":"article","titre":"Extrait de la préface « Le Roman »","blocs":["Le réaliste, s’il est un artiste, cherchera, non pas à nous montrer la photographie banale de la vie, mais à nous en donner la vision plus complète, plus saisissante, plus probante que la réalité même.","Faire vrai consiste donc à donner l’illusion complète du vrai."],"source":"Guy de Maupassant, préface de *Pierre et Jean*, « Le Roman » (1888)"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léo","emoji":"👦","cote":"gauche"},{"nom":"Maya","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Léo","texte":"Le réaliste enregistre tout, comme un appareil photo."},{"qui":"Maya","texte":"Maupassant dit l’inverse : il choisit et compose pour donner l’illusion du vrai."}]}],"questions":[{"enonce":"Touche le mot que Maupassant refuse comme modèle du roman.","aide":"Un procédé d’enregistrement du réel.","type":"zone","document":"preface","multiple":false},{"enonce":"Touche le mot qui dit ce que doit produire le romancier.","aide":"Faire vrai, ce n’est pas être vrai.","type":"zone","document":"preface","multiple":false},{"enonce":"Laquelle des deux lectures le texte confirme-t-il ?","aide":"Relis les mots de la préface : « non pas… mais… ».","type":"choix","options":[{"id":"a","texte":"Celle de Léo : le romancier enregistre tout"},{"id":"b","texte":"Aucune : Maupassant refuse le réalisme"},{"id":"c","texte":"Celle de Maya : le romancier choisit et compose"},{"id":"d","texte":"Les deux : tout est vrai dans un roman"}],"multiple":false},{"enonce":"Range chaque geste : le réaliste de Maupassant le fait, ou le refuse ?","aide":"Distingue la composition de l’enregistrement.","type":"categories","categories":[{"id":"c0","texte":"Il le fait"},{"id":"c1","texte":"Il le refuse"}],"items":[{"id":"i0","texte":"Choisir et composer"},{"id":"i1","texte":"Enregistrer tout comme un appareil"},{"id":"i2","texte":"Donner l’illusion du vrai"},{"id":"i3","texte":"Montrer la photographie banale de la vie"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"Maupassant refuse la **photographie** banale de la vie : le roman ne copie pas le réel, il le compose."},{"cle":{"type":"zone","ids":["m43"]},"explication":"Il faut donner l’**illusion** complète du vrai : un effet, non une copie."},{"cle":{"type":"choix","ids":["c"]},"explication":"Maupassant refuse la photographie : le romancier **choisit** et compose pour donner l’illusion du vrai."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Il **choisit** et donne l’**illusion** du vrai ; il **refuse** de tout enregistrer et de photographier la vie."}]$ex$::jsonb),
