   $ex${"titre":"Du tableau au feutre","competence":"analyser-document","situation":"Le tableau de Serge déclenche une dispute qui dure une heure et demie. Suis le fil de la pièce, puis dis ce que la dispute cache vraiment.","documents":[{"id":"fil","type":"chaine","titre":"Le fil de la pièce","disposition":"colonne","noeuds":[{"id":"z1","texte":"Serge achète un tableau blanc"},{"id":"z2","texte":"Marc le trouve ridicule"},{"id":"z3","texte":"La discussion devient un règlement de comptes"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Le feutre était lavable"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"L’étape qui précède la révélation du feutre : c’est un geste de Marc sur la toile.","type":"choix","options":[{"id":"a","texte":"Marc rachète le tableau à Serge pour le détruire devant tous"},{"id":"b","texte":"Serge se fait rembourser et rend le tableau à la galerie"},{"id":"c","texte":"Serge tend un feutre à Marc, qui dessine un skieur sur la toile"},{"id":"d","texte":"Yvan emporte la toile chez lui pour la nettoyer au solvant"}],"multiple":false},{"enonce":"Serge savait quelque chose depuis le début et ne l’a pas dit à Marc. Touche l’étape qui le révèle.","aide":"Qu’est-ce que Serge savait du feutre ?","type":"zone","document":"fil","multiple":false},{"enonce":"Relie chaque personnage à ce qu’il reproche, ou à ce qui lui arrive, dans la dispute.","aide":"Marc parle du goût de Serge ; Serge répond sur le rôle que Marc s’attribue.","type":"association","gauche":[{"id":"g0","texte":"Marc"},{"id":"g1","texte":"Serge"},{"id":"g2","texte":"Yvan"}],"droite":[{"id":"d0","texte":"Vouloir rester son maître à penser"},{"id":"d1","texte":"S’être inventé un goût pour se distinguer"},{"id":"d2","texte":"Tenter de ménager tout le monde, puis craquer"}]},{"enonce":"Range chaque élément : sujet apparent de la pièce ou vrai sujet ?","aide":"Le tableau est ce dont on parle ; l’amitié est ce qui se joue.","type":"categories","categories":[{"id":"c0","texte":"Sujet apparent"},{"id":"c1","texte":"Vrai sujet"}],"items":[{"id":"i0","texte":"La peur d’être exclu"},{"id":"i1","texte":"L’amitié masculine"},{"id":"i2","texte":"Le tableau blanc d’Antrios"},{"id":"i3","texte":"L’art contemporain"},{"id":"i4","texte":"Le besoin d’être admiré"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Serge **tend un feutre à Marc, qui dessine un skieur** sur la toile : c’est la preuve que l’amitié compte plus que l’objet."},{"cle":{"type":"zone","ids":["z5"]},"explication":"Le feutre était **lavable** : Serge le savait et s’est tu, l’amitié repart sur un petit mensonge."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Marc reproche à Serge de **s’être inventé un goût**, Serge à Marc de vouloir rester son **maître à penser**, et Yvan **craque** à force de ménager chacun."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"Le **tableau** et l’**art contemporain** sont le prétexte ; le vrai sujet est l’**amitié**, avec la peur d’être exclu et le besoin d’être admiré."}]$ex$::jsonb),
  ('99322c2e-8bb5-5b9b-8820-f4bcf9cc79b8'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une dispute sur un vélo","competence":"argumenter","situation":"Pour t’entraîner à l’oral, tu lis une courte scène écrite à la manière de Reza, puis tu t’en sers pour construire un petit argumentaire sur la pièce.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Une scène à la manière de « Art »","blocs":[{"didascalie":"Alex vient d’acheter un vélo de course très cher. Samir en fait le tour, sans rien dire."},{"personnage":"Alex","replique":"Dis-le. Tu trouves ça ridicule."},{"personnage":"Samir","replique":"Deux mille euros, pour rouler sur la même route que moi, avec mon vieux vélo ? Je n’ai rien dit."},{"personnage":"Alex","replique":"Justement. Avant, tu me donnais ton avis sur tout."},{"didascalie":"Samir, au public."},{"personnage":"Samir","replique":"Ce n’est pas le vélo. C’est qu’il n’a plus besoin de moi."}],"source":"Texte écrit pour l’exercice, à la manière de « Art » de Yasmina Reza"},{"id":"these","type":"tableau","titre":"Un petit argumentaire","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le tableau n’est qu’un prétexte","Les amis se disputent sur eux-mêmes, non sur la toile","Marc reproche à Serge de s’être inventé un goût"],["Le rire touche au grave","?","Yvan craque au milieu de la pièce"]],"enteteLignes":true}],"questions":[{"enonce":"Dans la scène, touche les deux mots qui montrent que le vrai sujet n’est pas le vélo.","aide":"Cherche ce qu’Alex regrette, et ce que Samir craint de perdre.","type":"zone","document":"scene","multiple":true},{"enonce":"Range chaque élément de la scène : il fait sourire, ou il touche au grave ?","aide":"Demande-toi : qu’est-ce qu’on peut dire à voix haute, qu’est-ce qu’on confie au public ?","type":"categories","categories":[{"id":"c0","texte":"Il fait sourire"},{"id":"c1","texte":"Il touche au grave"}],"items":[{"id":"i0","texte":"La peur de ne plus être utile à son ami"},{"id":"i1","texte":"Deux mille euros pour rouler sur la même route"},{"id":"i2","texte":"Un aveu fait au public, loin de l’autre"},{"id":"i3","texte":"« Je n’ai rien dit. » — « Justement. »"}]},{"enonce":"Relie chaque procédé de la scène à son effet.","aide":"Pense à ce que le public entend et que l’autre personnage n’entend pas.","type":"association","gauche":[{"id":"g0","texte":"Des répliques très brèves"},{"id":"g1","texte":"Une adresse au public"},{"id":"g2","texte":"Un objet banal (un vélo)"}],"droite":[{"id":"d0","texte":"Un prétexte qui laisse voir le vrai sujet"},{"id":"d1","texte":"Le personnage confie ce qu’il n’ose pas dire à l’autre"},{"id":"d2","texte":"Le rythme d’une dispute qui s’emballe"}]},{"enonce":"Quelle phrase complète la case « ? » du tableau (le rire touche au grave) ?","aide":"Relis ce que le cours dit du rire dans cette comédie.","type":"choix","options":[{"id":"a","texte":"Derrière le comique, on entend la solitude de chacun"},{"id":"b","texte":"Le public rit, donc il n’y a rien de sérieux"},{"id":"c","texte":"Les répliques sont brèves, donc la pièce reste légère"},{"id":"d","texte":"Le décor unique fait oublier les personnages"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m49","m68"]},"explication":"Les mots **avis** et **besoin** disent ce qui est en jeu : le rôle que chacun tient dans l’amitié, comme chez Reza."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Le prix du vélo et le quiproquo **font sourire** ; la peur d’être abandonné et l’aveu au public **touchent au grave** : c’est le mélange de « Art »."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Les répliques brèves donnent du **rythme**, l’adresse au public **confie** l’indicible, l’objet banal est un **prétexte** : trois procédés de Reza."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le rire y **fait entendre la solitude de chacun** : c’est ce qui fait de « Art » une comédie qui touche au grave."}]$ex$::jsonb),
