  ('3ab11489-ba23-5635-9955-6f95473aa7d5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du fleuve à la flaque","competence":"analyser-texte","situation":"Le bateau descend un fleuve, se perd en mer, puis rêve de retour. Lis les deux premiers vers, puis remets en ordre les trois temps du poème.","documents":[{"id":"debut","type":"texte","genre":"poeme","titre":"Le début du poème","blocs":["Comme je descendais des Fleuves impassibles,","Je ne me sentis plus guidé par les haleurs :"],"source":"Arthur Rimbaud, *Le Bateau ivre* (1871), vers 1 et 2"},{"id":"temps","type":"tableau","titre":"Les trois temps du poème (en désordre)","colonnes":["Temps","Ce qui s’y passe"],"lignes":[["La fatigue","Le désir de retour : une « flache noire et froide » d’Europe"],["La libération","Plus d’équipage, plus de gouvernail"],["?","« Poème de la mer », soleils, aurores, cataractes, monstres"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne ceux qui tiraient le bateau le long du fleuve.","aide":"Ce sont des hommes qui marchaient sur la berge.","type":"zone","document":"debut","multiple":false},{"enonce":"Que signifie, dès le début, la fin des haleurs ?","aide":"Qui conduisait le bateau avant, et que devient-il ensuite ?","type":"choix","options":[{"id":"a","texte":"Le poète renonce au voyage et rentre chez lui"},{"id":"b","texte":"Le bateau n’est plus guidé : il se libère de toute contrainte"},{"id":"c","texte":"Le bateau est abandonné par des marins qui ont peur"},{"id":"d","texte":"Le fleuve devient trop étroit pour être halé"}],"multiple":false},{"enonce":"Trouve le nom du temps manquant (la case « ? »).","aide":"Soleils, aurores, monstres : le bateau voit des choses inouïes.","type":"trous","segments":["Entre la libération et la fatigue vient l’",0," de la ",1,"."],"banque":["ivresse","prière","fatigue","mer","vision"]},{"enonce":"Remets les trois temps du poème dans l’ordre où on les lit.","aide":"On part d’un bateau libre pour finir par le désir du retour.","type":"ordre","items":[{"id":"a","texte":"L’ivresse de la vision"},{"id":"b","texte":"La fatigue"},{"id":"c","texte":"La libération"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"Les **haleurs** guidaient le bateau ; leur disparition ouvre le poème."},{"cle":{"type":"choix","ids":["b"]},"explication":"Sans haleurs, ni équipage, ni gouvernail, le bateau est **libre** : c’est le premier temps du poème, la libération."},{"cle":{"type":"trous","trous":[["ivresse"],["vision"]]},"affichage":"ivresse · vision","explication":"Le temps du milieu est **l’ivresse de la vision** : le bateau voit ce que l’homme a cru voir, et même plus."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Ordre du poème : **libération**, **ivresse de la vision**, **fatigue** (le désir d’une flaque d’Europe)."}]$ex$::jsonb),
  ('3ab11489-ba23-5635-9955-6f95473aa7d5'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un voyage que Rimbaud n’a jamais fait","competence":"argumenter","situation":"Deux élèves se disputent sur ce poème : un vrai voyage en mer, ou autre chose ? Tranche avec le dialogue et les derniers vers.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Elsa","emoji":"👧","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Elsa","texte":"Rimbaud a forcément traversé l’océan : tout est trop précis pour être inventé."},{"qui":"Karim","texte":"Il a seize ans et n’a jamais vu la mer. Ses images viennent de ses lectures."},{"qui":"Elsa","texte":"Alors le poème ne serait qu’un exercice de style ?"},{"qui":"Karim","texte":"Non : c’est le programme de la lettre du Voyant, mis en images."}]},{"id":"fin","type":"texte","genre":"poeme","titre":"Les derniers vers","blocs":["Ni traverser l’orgueil des drapeaux et des flammes,","Ni nager sous les yeux horribles des pontons."],"source":"Arthur Rimbaud, *Le Bateau ivre* (1871), derniers vers"}],"questions":[{"enonce":"Touche le mot qui dit d’où viennent les images exotiques du poème.","aide":"Karim répond à Elsa : il rappelle ce que Rimbaud a lu, pas ce qu’il a vu.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche les deux verbes qui disent ce que le bateau refuse de faire.","aide":"Les deux vers commencent par « Ni » : cherche le verbe qui suit.","type":"zone","document":"fin","multiple":true},{"enonce":"Relie chaque procédé du poème à son effet.","aide":"Pense à ce que le vers imite, et à ce que l’on gagne à parler par la voix d’un bateau.","type":"association","gauche":[{"id":"g0","texte":"Vingt-cinq quatrains d’alexandrins"},{"id":"g1","texte":"Allitérations, néologismes, rythme"},{"id":"g2","texte":"Le « je » d’un bateau libre"}],"droite":[{"id":"d0","texte":"Le vers bouge comme l’eau"},{"id":"d1","texte":"Une forme régulière qui contraste avec le déferlement des images"},{"id":"d2","texte":"Le poète se projette dans un objet qui s’abandonne à l’inconnu"}]},{"enonce":"Quelle conclusion de dissertation ce poème permet-il le mieux d’appuyer ?","aide":"Un poète qui n’a jamais vu la mer écrit le « Poème de la mer ».","type":"choix","options":[{"id":"a","texte":"La poésie doit décrire fidèlement les voyages réels que le poète a vécus"},{"id":"b","texte":"La poésie est d’abord un récit d’aventures maritimes destiné à la jeunesse"},{"id":"c","texte":"La poésie peut être une exploration de l’inconnu plutôt qu’une description du réel"},{"id":"d","texte":"La poésie perd sa valeur dès qu’elle emploie des vers réguliers et rimés"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"L’exotisme est **livresque** : ces images viennent des **lectures** d’enfance, pas d’un voyage réel."},{"cle":{"type":"zone","ids":["m1","m10"]},"explication":"Le bateau refuse de **traverser** l’orgueil des drapeaux et de **nager** sous les yeux des pontons, ces navires-prisons."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"La **forme régulière** contraste avec le déferlement ; le **rythme** fait bouger le vers comme l’eau ; le **bateau** est le masque du poète voyant."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le poème montre que la poésie peut être une **exploration de l’inconnu** : c’est le poète voyant de la lettre du Voyant."}]$ex$::jsonb),
