  ('aa2fb3c9-259c-5177-9ad4-85f2bb0c456f'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Une fête au Valois","competence":"se-reperer-temps","situation":"Un simple journal suffit à faire partir le narrateur de Paris. Lis ce résumé, puis démêle les époques qui s’y superposent.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"Le départ pour le Valois","blocs":["Un soir, à Paris, le narrateur lit un entrefilet : une fête a lieu cette nuit-là au Valois, le pays de son enfance. Il part aussitôt, et son voyage de nuit réveille ses souvenirs.","Il revoit d’abord l’adolescence : Sylvie, la paysanne, et les promenades d’autrefois. Plus loin encore, il se rappelle Adrienne, aperçue une seule fois, chantant dans une ronde.","Le récit passe d’une époque à l’autre en une phrase, sans prévenir le lecteur."],"source":"Résumé écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui déclenche le départ du narrateur.","aide":"C’est un petit texte de journal.","type":"zone","document":"resume","multiple":false},{"enonce":"Range chaque élément dans l’époque du récit à laquelle il appartient.","aide":"Le résumé dit quel souvenir vient « d’abord » et lequel vient « plus loin encore ».","type":"categories","categories":[{"id":"c0","texte":"Aujourd’hui"},{"id":"c1","texte":"L’adolescence"},{"id":"c2","texte":"Le souvenir lointain"}],"items":[{"id":"i0","texte":"Adrienne chantant dans une ronde"},{"id":"i1","texte":"Le voyage de nuit"},{"id":"i2","texte":"La fête annoncée au Valois"},{"id":"i3","texte":"Sylvie, la paysanne"}]},{"enonce":"Remets dans l’ordre les grands moments du récit, du début à la fin.","aide":"Le récit commence à Paris et finit sur une leçon.","type":"ordre","items":[{"id":"a","texte":"Il part vers le pays de son enfance"},{"id":"b","texte":"Il passe ses soirées au théâtre, pour Aurélie"},{"id":"c","texte":"« Dernier feuillet » : le récit tire la leçon de ses illusions"},{"id":"d","texte":"Sylvie a épousé « le grand frisé »"},{"id":"e","texte":"Un entrefilet lui apprend qu’une fête a lieu au Valois"}]}]}$ex$::jsonb,
