   $ex${"titre":"La dernière phrase","competence":"analyser-texte","situation":"Flaubert écrit ce conte pour George Sand, qui lui reprochait d’être sans cœur. Lis la dernière phrase et dis comment il lui répond.","documents":[{"id":"fin","type":"texte","genre":"recit","titre":"La mort de Félicité","blocs":["… et, quand elle exhala son dernier souffle, elle crut voir, dans les cieux entr’ouverts, un perroquet gigantesque, planant au-dessus de sa tête."],"source":"Gustave Flaubert, *Un cœur simple* (1877), dernière phrase"},{"id":"style","type":"tableau","titre":"Ce que le style refuse","colonnes":["Ce que le style refuse","Ce qu’il obtient"],"lignes":[["Toute ironie envers Félicité","?"],["Tout pathos","Une émotion d’autant plus forte"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui montrent que ce que voit Félicité est une vision, et non un fait.","aide":"Cherche le verbe qui dit qu’elle imagine et celui qui dit ce qu’elle imagine.","type":"zone","document":"fin","multiple":true},{"enonce":"Que met-on dans la case « ? » : ce qu’obtient un style qui refuse l’ironie envers Félicité ?","aide":"Le style est dépouillé, sans commentaire.","type":"choix","options":[{"id":"a","texte":"Un lyrisme appuyé"},{"id":"b","texte":"Un récit de miracle"},{"id":"c","texte":"Une moquerie légère"},{"id":"d","texte":"Une sobriété absolue"}],"multiple":false},{"enonce":"Relie chaque choix de Flaubert à son effet.","aide":"Pense à ce que le conte donne à une servante illettrée.","type":"association","gauche":[{"id":"g0","texte":"Pas de pathos"},{"id":"g1","texte":"Une confusion prise absolument au sérieux"},{"id":"g2","texte":"Un oiseau empaillé"}],"droite":[{"id":"d0","texte":"La grandeur d’une vie de sainte donnée à une vie minuscule"},{"id":"d1","texte":"Une émotion d’autant plus forte"},{"id":"d2","texte":"Un objet dérisoire qui reçoit tout l’amour de Félicité"}]},{"enonce":"Complète pour montrer comment Flaubert répond à George Sand.","aide":"Le reproche est d