  ('942120a6-b499-5b9d-9ee3-6001b3255ab2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Au bureau des archives","competence":"analyser-texte","situation":"Pour comprendre le métier de Winston, lis une courte scène écrite pour l’exercice, puis relie les notions du roman à ce qu’elles font.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Une journée au ministère de la Vérité","blocs":["Dans le bureau des archives d’Océania, un employé reçoit une vieille page de journal. Une prévision du Parti s’y est révélée fausse.","Il la réécrit pour que le Parti ait toujours eu raison, puis détruit l’ancienne page. Au mur, le télécran ne le quitte pas des yeux."],"source":"Texte écrit pour l’exercice, à la manière de *1984* d’Orwell"}],"questions":[{"enonce":"Touche les deux mots qui décrivent le travail de cet employé, le même que celui de Winston.","aide":"Que fait-il subir au passé ?","type":"zone","document":"scene","multiple":true},{"enonce":"Touche le mot qui désigne la surveillance permanente.","aide":"C’est un appareil accroché au mur.","type":"zone","document":"scene","multiple":false},{"enonce":"Relie chaque notion du roman à ce qu’elle fait.","aide":"Chaque notion décrit un moyen du Parti de contrôler les esprits ou les corps.","type":"association","gauche":[{"id":"g0","texte":"Le novlangue"},{"id":"g1","texte":"La double-pensée"},{"id":"g2","texte":"Les télécrans"},{"id":"g3","texte":"Les Deux Minutes de la Haine"}],"droite":[{"id":"d0","texte":"Ils assurent la surveillance permanente"},{"id":"d1","texte":"Elles détournent la colère sur Goldstein"},{"id":"d2","texte":"Il appauvrit la langue et rend la révolte impensable"},{"id":"d3","texte":"Elle permet de croire deux choses contradictoires à la fois"}]},{"enonce":"Que montre cette scène du pouvoir d’Océania ?","aide":"Qui contrôle le passé contrôle l’avenir.","type":"choix","options":[{"id":"a","texte":"Il se contente de punir ceux qui désobéissent"},{"id":"b","texte":"Il ne surveille que les chefs du Parti"},{"id":"c","texte":"Il laisse chacun libre de lire ses archives"},{"id":"d","texte":"Il s’attaque d’abord à la mémoire et au langage"}],"multiple":false}]}$ex$::jsonb,
