   $ex${"titre":"Des mots pour ne plus penser","competence":"argumenter","situation":"Une dictature peut-elle tuer une idée en tuant le mot ? Lis un échange écrit à la manière du roman, puis construis ton argument.","documents":[{"id":"canti","type":"texte","genre":"theatre","titre":"À la cantine du ministère","blocs":[{"didascalie":"Deux collègues parlent du dictionnaire de la nouvelle langue."},{"personnage":"Marek","replique":"Chaque année, nous supprimons des mots. Quand « révolte » aura disparu, personne ne pourra plus la penser."},{"personnage":"Dora","replique":"Et ceux qui la pensent déjà ?"},{"personnage":"Marek","replique":"Ils n’auront plus personne à qui la dire."}],"source":"Texte écrit pour l’exercice, à la manière de *1984* d’Orwell"},{"id":"these","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Un pouvoir total s’attaque d’abord au langage","Sans mots pour la penser, la révolte devient impossible","?"],["… et à la mémoire","Qui contrôle le passé contrôle l’avenir","Winston réécrit les archives"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe qui dit ce que le Parti fait aux mots, puis celui qui dit ce que les gens ne pourront plus faire.","aide":"Un verbe pour le Parti, un verbe pour les gens ordinaires.","type":"zone","document":"canti","multiple":true},{"enonce":"Quel exemple du roman faut-il écrire dans la case « ? » du tableau ?","aide":"C’est la langue appauvrie qui rend la révolte impensable.","type":"choix","options":[{"id":"a","texte":"Les Deux Minutes de la Haine"},{"id":"b","texte":"Le novlangue"},{"id":"c","texte":"La chambre 101"},{"id":"d","texte":"Le journal de Winston"}],"multiple":false},{"enonce":"Range chaque dispositif : il sert à surveiller et punir, ou à façonner la pensée ?","aide":"Demande-toi : agit-il sur les corps, ou sur ce que l’on peut penser et se rappeler ?","type":"categories","categories":[{"id":"c0","texte":"Surveiller et punir"},{"id":"c1","texte":"Façonner la pensée"}],"items":[{"id":"i0","texte":"Les télécrans"},{"id":"i1","texte":"La réécriture des archives"},{"id":"i2","texte":"La double-pensée"},{"id":"i3","texte":"Le novlangue"},{"id":"i4","texte":"La chambre 101"}]},{"enonce":"Comment le cours définit-il le genre du roman ?","aide":"Le mot préfixé « contre- » indique le renversement d’un rêve de société parfaite.","type":"choix","options":[{"id":"a","texte":"Une utopie, qui décrit une société idéale et heureuse"},{"id":"b","texte":"Un reportage sur la guerre d’Espagne et ses milices"},{"id":"c","texte":"Un conte pour enfants sur des animaux de la ferme"},{"id":"d","texte":"Une contre-utopie, qui imagine le pire pour en avertir"}],"multiple":false}]}$ex$::jsonb,
