  ('44b29d11-96e4-5d77-97f8-17949ff4ff53'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Valmer, un nom trop rêvé","competence":"analyser-texte","situation":"Proust aime montrer l’écart entre un nom rêvé et la chose vue. Lis ce pastiche écrit pour l’exercice, puis tranche un petit débat.","documents":[{"id":"pastiche","type":"texte","genre":"recit","titre":"Un pastiche","blocs":["Tout l’hiver, Valmer n’avait été pour moi qu’un nom, si doré, si lointain, que je le croyais gros de toutes les tempêtes et de toutes les églises de la terre ; aussi, le soir où le train me déposa devant une gare semblable à toutes les gares, la ville que je découvris, banale et sans mystère, me causa-t-elle la déception de ceux qui ont trop longtemps rêvé."],"source":"Texte écrit pour l’exercice, à la manière de Marcel Proust"},{"id":"deb","type":"dialogue","titre":"Un débat","modele":"bulles","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Ravi","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"On lit Proust pour savoir ce qui arrive à Albertine : c’est l’intrigue qui compte."},{"qui":"Ravi","texte":"Pas dans ce volume : presque rien n’arrive. On suit plutôt un regard qui apprend à voir."}]}],"questions":[{"enonce":"Touche le mot qui dit ce qu’était Valmer avant d’être vue.","aide":"La ville n’existait encore que par un mot.","type":"zone","document":"pastiche","multiple":false},{"enonce":"Touche les deux mots qui disent ce que le narrateur éprouve devant la réalité.","aide":"Un adjectif pour la ville, un nom pour le sentiment.","type":"zone","document":"pastiche","multiple":true},{"enonce":"Relie chaque trait de l’écriture de Proust à son effet.","aide":"Pense à la phrase, au nom et au peintre.","type":"association","gauche":[{"id":"g0","texte":"Une phrase longue, ramifiée, à incises"},{"id":"g1","texte":"Un nom rêvé face à la chose vue"},{"id":"g2","texte":"Elstir qui apprend à voir"}],"droite":[{"id":"d0","texte":"Elle épouse le mouvement d’une conscience"},{"id":"d1","texte":"Un regard nouveau sur le monde par l’art"},{"id":"d2","texte":"La déception"}]},{"enonce":"Quelle position le cours soutient-il dans le débat ?","aide":"Le cours dit : ce n’est pas un roman d’action.","type":"choix","options":[{"id":"a","texte":"Mia : Albertine est l’héroïne d’une grande intrigue amoureuse"},{"id":"b","texte":"Ravi : le livre est l’apprentissage d’un regard, pas un roman d’action"},{"id":"c","texte":"Ravi : le livre raconte la guerre de 1914-1918"},{"id":"d","texte":"Mia : le livre vaut par la suite de ses péripéties"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"Valmer n’était qu’un **nom** : c’est l’écart entre le nom rêvé et la chose vue qui produit la déception."},{"cle":{"type":"zone","ids":["m54","m61"]},"explication":"La ville est **banale**, et le narrateur éprouve de la **déception** : le motif revient avec l’église de Balbec et la Berma."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"La **phrase** suit la conscience, le **nom rêvé** mène à la déception, et **Elstir** ouvre un regard nouveau."},{"cle":{"type":"choix","ids":["b"]},"explication":"On ne lit pas Proust pour savoir ce qui arrive : c’est l’**apprentissage d’un regard**, comme le dit Ravi."}]$ex$::jsonb),
  ('76f3de38-2adb-5217-a10a-988bbe964a20'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un amour qui s’éteint","competence":"se-reperer-temps","situation":"Adolphe séduit Ellénore, puis ne sait plus comment la quitter. Suis les étapes de cette liaison, de la séduction à la fin.","documents":[{"id":"fil","type":"chaine","titre":"La liaison d’Adolphe et d’Ellénore","disposition":"colonne","noeuds":[{"id":"z1","texte":"Adolphe séduit Ellénore, par vanité"},{"id":"z2","texte":"Ellénore quitte tout pour lui"},{"id":"z3","texte":"Aussitôt qu’il l’a obtenue, il cesse de l’aimer"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Ellénore meurt après avoir lu sa lettre"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Adolphe n’aime plus, mais il n’a pas le courage de rompre.","type":"choix","options":[{"id":"a","texte":"Il l’avoue aussitôt à Ellénore et la quitte sans un regard"},{"id":"b","texte":"Il part pour la Pologne afin d’oublier tout à fait Ellénore"},{"id":"c","texte":"Il épouse Ellénore pour apaiser son père et la société"},{"id":"d","texte":"Il n’ose pas le lui dire : il reste par pitié et par faiblesse"}],"multiple":false},{"enonce":"Touche l’étape où le sentiment d’Adolphe se retourne.","aide":"Cherche ce qui arrive dès qu’il a obtenu ce qu’il voulait.","type":"zone","document":"fil","multiple":false},{"enonce":"Relie chaque personnage à son rôle.","aide":"Le baron de T. est un ami du père d’Adolphe.","type":"association","gauche":[{"id":"g0","texte":"Adolphe"},{"id":"g1","texte":"Ellénore"},{"id":"g2","texte":"Le père d’Adolphe"},{"id":"g3","texte":"Le baron de T."}],"droite":[{"id":"d0","texte":"Il désapprouve la liaison, à distance"},{"id":"d1","texte":"Un jeune homme lucide sur lui-même mais incapable d’agir"},{"id":"d2","texte":"D’origine polonaise, maîtresse d’un comte, elle quitte tout pour lui"},{"id":"d3","texte":"Il pousse Adolphe à rompre et fait parvenir sa lettre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Adolphe **n’ose pas le dire** : il reste par **pitié**, par **faiblesse**, par peur de la faire souffrir, et cette indécision dure des années."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Dès qu’il l’a **obtenue**, il cesse de l’aimer : la vanité qui l’avait poussé à séduire disparaît avec la conquête."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"**Adolphe** voit tout sans agir, **Ellénore** sacrifie tout, le **père** désapprouve, le **baron de T.** pousse à la rupture."}]$ex$::jsonb),
  ('76f3de38-2adb-5217-a10a-988bbe964a20'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un manuscrit trouvé","competence":"se-reperer-temps","situation":"Le livre se présente comme un manuscrit retrouvé et publié par un « éditeur ». Place-le dans la vie de Constant, puis lis l’avertissement imaginé pour l’exercice.","documents":[{"id":"frise","type":"frise","titre":"Constant et son livre","debut":1760,"fin":1835,"pas":5,"evenements":[{"id":"z1","date":1767,"nom":"Naissance"},{"id":"z2","date":1806,"nom":"Adolphe écrit"},{"id":"z3","date":1816,"nom":"Adolphe publié"},{"id":"z4","date":1830,"nom":"Mort"}]},{"id":"avert","type":"texte","genre":"lettre","titre":"Un avertissement imaginé","blocs":["J’ai trouvé ce manuscrit dans les papiers d’un inconnu. Je le publie tel qu’il m’est venu, sans en connaître l’auteur ni juger le héros."],"source":"Texte écrit pour l’exercice, à la manière de l’« éditeur » d’*Adolphe*"}],"questions":[{"enonce":"Combien d’années séparent l’écriture d’*Adolphe* de sa publication ?","aide":"Repère les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Touche le verbe par lequel l’« éditeur » prétend ne pas être l’auteur du récit.","aide":"Il dit seulement ce qu’il a fait du manuscrit.","type":"zone","document":"avert","multiple":false},{"enonce":"Range chaque trait d’*Adolphe* : il le rattache au romantisme, ou à la tradition classique ?","aide":"Le style dépouillé et l’analyse des motifs font penser au XVIIe siècle.","type":"categories","categories":[{"id":"c0","texte":"Par son époque et son thème, romantique"},{"id":"c1","texte":"Par sa manière, classique"}],"items":[{"id":"i0","texte":"Il est l’héritier de *La Princesse de Clèves*"},{"id":"i1","texte":"Son style est d’une sécheresse toute classique"},{"id":"i2","texte":"Il appartient à la génération du « mal du siècle »"},{"id":"i3","texte":"Il s’inscrit dans la génération romantique"},{"id":"i4","texte":"Presque pas d’action : tout est dans les motifs"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 ans","explication":"1816 − 1806 = **10 ans** : *Adolphe* est écrit en 1806 et publié en 1816."},{"cle":{"type":"zone","ids":["m2"]},"explication":"**Trouvé** : l’« éditeur » prétend n’avoir fait que retrouver et publier un manuscrit, comme dans le dispositif d’*Adolphe*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"Constant est **romantique** par sa génération et le « mal du siècle », mais **classique** par la sécheresse du style et l’analyse des motifs."}]$ex$::jsonb),
  ('76f3de38-2adb-5217-a10a-988bbe964a20'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Faible ou cruel ?","competence":"argumenter","situation":"Deux élèves portent un jugement opposé sur Adolphe. Appuie-toi sur le dialogue et sur une phrase du roman pour trancher.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"Adolphe est un manipulateur : il séduit Ellénore par vanité, puis il l’abandonne."},{"qui":"Hugo","texte":"Pas tout à fait : il ne la quitte jamais vraiment. Il reste par pitié et par faiblesse, et c’est cette indécision qui la tue."},{"qui":"Camille","texte":"Donc il n’est pas coupable ?"},{"qui":"Hugo","texte":"Si, mais autrement : il fait un mal immense en voulant éviter d’en faire."}]},{"id":"phrase","type":"texte","genre":"recit","titre":"Une phrase du roman","blocs":["« Malheur à l’homme qui, dans les premiers moments d’une liaison d’amour, ne croit pas que cette liaison doit être éternelle ! »"],"source":"Benjamin Constant, *Adolphe* (1816)"}],"questions":[{"enonce":"Touche le mot qui dit pourquoi Adolphe reste auprès d’Ellénore alors qu’il ne l’aime plus.","aide":"Hugo donne le motif juste après « Il reste par ».","type":"zone","document":"deb","multiple":false},{"enonce":"Touche le mot qui dit ce que celui qui commence une liaison doit croire de cette liaison.","aide":"Le mot est le dernier de la proposition, juste avant le point d’exclamation.","type":"zone","document":"phrase","multiple":false},{"enonce":"Relie chaque thème du roman à ce qu’il en dit.","aide":"Les trois thèmes s’opposent à ce qu’on attendrait d’un héros.","type":"association","gauche":[{"id":"g0","texte":"La faiblesse"},{"id":"g1","texte":"La société"},{"id":"g2","texte":"La lucidité"}],"droite":[{"id":"d0","texte":"Adolphe voit tout, et n’en fait rien"},{"id":"d1","texte":"Plus destructrice que la méchanceté"},{"id":"d2","texte":"Elle condamne la femme, pas l’homme"}]},{"enonce":"Quelle lecture d’Adolphe le cours permet-il de défendre ?","aide":"Hugo parle de faiblesse et d’indécision, pas de cruauté.","type":"choix","options":[{"id":"a","texte":"Un héros romantique que sa passion mène vers la gloire"},{"id":"b","texte":"Une victime de la société, qui n’a aucune part de responsabilité"},{"id":"c","texte":"Un séducteur cynique qui quitte Ellénore sans le moindre remords"},{"id":"d","texte":"Un faible, qui fait un mal immense en voulant l’éviter"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26"]},"explication":"Adolphe reste par **pitié**, et par faiblesse : il ne veut pas faire souffrir Ellénore, et il la fait mourir à petit feu."},{"cle":{"type":"zone","ids":["m22"]},"explication":"Il doit croire que sa liaison est **éternelle** : la phrase dit combien on se trompe sur la durée de l’amour."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La **faiblesse** détruit plus que la méchanceté, la **société** condamne la femme seule, la **lucidité** n’empêche pas d’agir mal."},{"cle":{"type":"choix","ids":["d"]},"explication":"Constant démonte la **mécanique de la lâcheté sentimentale** : Adolphe n’est ni un monstre ni un innocent, c’est un faible."}]$ex$::jsonb),
