   $ex${"titre":"Antigone a-t-elle raison ?","competence":"argumenter","situation":"Trois élèves discutent du conflit. Écoute leurs arguments, puis lis le chant du chœur pour mesurer la grandeur — et la limite — de l’homme.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léna","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"},{"nom":"Marthe","emoji":"🧑","cote":"gauche"}],"repliques":[{"qui":"Léna","texte":"Créon a raison : sans loi, la cité s’écroule. La cité passe avant tout."},{"qui":"Yanis","texte":"Non : aucun décret n’est supérieur aux lois non écrites des dieux. Un frère doit recevoir une sépulture."},{"qui":"Marthe","texte":"Vous avez chacun une part de vérité : aucun des deux n’a entièrement tort."}]},{"id":"choeur","type":"texte","genre":"poeme","titre":"Le chant du chœur (résumé)","blocs":["Il est bien des merveilles en ce monde, mais aucune n’est plus grande que l’homme, capable de tout, sauf de vaincre la mort."],"source":"Résumé du chant du chœur, d’après le cours"}],"questions":[{"enonce":"Range chaque argument : il défend Antigone ou Créon ?","aide":"Léna parle pour Créon, Yanis pour Antigone.","type":"categories","categories":[{"id":"c0","texte":"Antigone"},{"id":"c1","texte":"Créon"}],"items":[{"id":"i0","texte":"Sans loi, la cité s’écroule"},{"id":"i1","texte":"Un frère doit recevoir une sépulture"},{"id":"i2","texte":"Aucun décret n’est supérieur aux lois non écrites des dieux"},{"id":"i3","texte":"La cité passe avant tout"}]},{"enonce":"Pourquoi Marthe juge-t-elle la pièce « inépuisable » ?","aide":"Relis la dernière réplique de Marthe.","type":"choix","options":[{"id":"a","texte":"Parce qu’Antigone finit par donner raison à Créon"},{"id":"b","texte":"Parce que le chœur est le seul à avoir raison"},{"id":"c","texte":"Parce que Créon est puni par les dieux sans raison"},{"id":"d","texte":"Parce qu’aucun des deux n’a entièrement tort"}],"multiple":false},{"enonce":"Touche le mot qui dit la limite de l’homme.","aide":"Capable de tout, sauf d’une seule chose.","type":"zone","document":"choeur","multiple":false},{"enonce":"Complète ce qui perd Créon.","aide":"C’est un mot grec qui désigne la démesure.","type":"trous","segments":["L’",0,", la démesure, perd ",1," dans la pièce."],"banque":["Hémon","Créon","hybris","hamartia"]}]}$ex$::jsonb,
