   $ex${"titre":"Ce que le texte ne dit pas","competence":"analyser-texte","situation":"Dans *Armance*, tout se joue dans ce qu’on ne dit pas. Lis une scène de salon écrite pour l’exercice, puis tire les leçons du roman.","documents":[{"id":"salon","type":"texte","genre":"recit","titre":"Une scène de salon, à la manière de Stendhal","blocs":["Le salon de la marquise était plein ; on y parlait de l’indemnité, du prix des terres, d’un mariage conclu à Londres. Aurore traversa la pièce, s’arrêta devant Gaston, et lui dit seulement qu’il faisait chaud. Il répondit qu’en effet il faisait chaud. Puis tous deux regardèrent, avec une attention extraordinaire, le dessin du tapis."],"source":"Texte écrit pour l’exercice, à la manière de Stendhal"},{"id":"acquis","type":"tableau","titre":"Ce qu’on y trouve déjà","colonnes":["Ce qu’on y trouve","Où"],"lignes":[["La peinture d’une société","Le salon aristocratique de la Restauration, l’argent, les calculs de mariage"],["L’analyse d’une conscience","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que l’attention portée au tapis n’est qu’un prétexte.","aide":"Un tapis ne mérite pas une telle attention.","type":"zone","document":"salon","multiple":false},{"enonce":"Quelle réponse compléter la case « ? » du tableau ?","aide":"Pense à ce qui empêche Octave d’être l’époux de qui que ce soit.","type":"choix","options":[{"id":"a","texte":"Une conscience heureuse de son rôle mondain"},{"id":"b","texte":"Une conscience délivrée par la fortune"},{"id":"c","texte":"Une conscience tournée vers la politique"},{"id":"d","texte":"Une conscience prise dans son propre secret"}],"multiple":false},{"enonce":"Relie chaque procédé du roman à son effet.","aide":"Pense au secret, au style et au sous-titre.","type":"association","gauche":[{"id":"g0","texte":"Un secret jamais nommé"},{"id":"g1","texte":"Un style retenu, allusif"},{"id":"g2","texte":"Le sous-titre « Quelques scènes d’un salon de Paris en 1827 »"}],"droite":[{"id":"d0","texte":"Il annonce une peinture de société plutôt qu’une aventure"},{"id":"d1","texte":"Le lecteur doit deviner ce que le texte refuse de nommer"},{"id":"d2","texte":"Il a dérouté les lecteurs de 1827"}]},{"enonce":"Complète la conclusion de dissertation.","aide":"Le roman cache plus qu’il ne dit.","type":"trous","segments":["*Armance* est un roman du ",0," : le sens naît de ce que le texte ",1," de nommer."],"banque":["dit","refuse","accepte","non-dit"]}]}$ex$::jsonb,
